`Navigator` models one probe on a rectangular field whose valid coordinates are `0 <= x < width` and `0 <= y < height`. Constructor dimensions must be positive integers. Before placement, `turnLeft`, `turnRight`, and `advance` return `false`. `place` returns `false` and leaves state unchanged for noninteger or out-of-bounds coordinates; otherwise it stores the position and heading and returns `true`. Turns rotate 90 degrees and return `true`. `advance` moves one cell and returns `true`, or returns `false` without moving at an edge. `snapshot` returns a new frozen object, or `undefined` before placement.

Known-bad source:
```typescript
export enum Heading { North, East, South, West }
export interface ProbeSnapshot { x: number; y: number; heading: Heading }

export class Navigator {
  private current: ProbeSnapshot | undefined;

  constructor(private readonly width: number, private readonly height: number) {
    if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0) {
      throw new RangeError("invalid field dimensions");
    }
  }

  place(x: number, y: number, heading: Heading): boolean {
    if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || y < 0 || x >= this.width || y >= this.height) return false;
    this.current = { x, y, heading };
    return true;
  }

  turnLeft(): boolean {
    if (!this.current) return false;
    this.current.heading = (this.current.heading + 3) % 4;
    return true;
  }

  turnRight(): boolean {
    if (!this.current) return false;
    this.current.heading = (this.current.heading + 1) % 4;
    return true;
  }

  advance(): boolean {
    if (!this.current) return false;
    const dx = [0, 1, 0, -1][this.current.heading];
    const dy = [1, 0, -1, 0][this.current.heading];
    const nx = this.current.x + dx, ny = this.current.y + dy;
    if (nx < 0 || ny < 0 || nx <= this.width || ny >= this.height) return false;
    this.current.x = nx;
    this.current.y = ny;
    return true;
  }

  snapshot(): Readonly<ProbeSnapshot> | undefined {
    return this.current ? Object.freeze({ ...this.current }) : undefined;
  }
}
```

