import { Heading, Navigator } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

for (const dimensions of [[0, 1], [1, 0], [-1, 1], [1.5, 2], [2, NaN], [Infinity, 2]]) {
  throwsRange(() => new Navigator(dimensions[0], dimensions[1]), 'invalid dimensions');
}

const unplaced = new Navigator(3, 2);
equal(unplaced.snapshot(), undefined, 'snapshot before placement');
equal(unplaced.turnLeft(), false, 'left before placement');
equal(unplaced.turnRight(), false, 'right before placement');
equal(unplaced.advance(), false, 'advance before placement');

assert(unplaced.place(1, 0, Heading.North), 'valid placement');
const snapshot1 = unplaced.snapshot()!;
equal(snapshot1.x, 1, 'placed x');
equal(snapshot1.y, 0, 'placed y');
equal(snapshot1.heading, Heading.North, 'placed heading');
assert(Object.isFrozen(snapshot1), 'snapshot frozen');
const snapshot2 = unplaced.snapshot()!;
assert(snapshot2 !== snapshot1, 'snapshot is new each call');

for (const [x, y] of [[-1, 0], [0, -1], [3, 0], [0, 2], [0.5, 0], [0, 1.5], [NaN, 0]]) {
  equal(unplaced.place(x, y, Heading.South), false, 'invalid placement rejected');
  const stable = unplaced.snapshot()!;
  equal(stable.x, 1, 'invalid placement preserves x');
  equal(stable.y, 0, 'invalid placement preserves y');
  equal(stable.heading, Heading.North, 'invalid placement preserves heading');
}

equal(unplaced.advance(), true, 'north advance');
equal(unplaced.snapshot()!.y, 1, 'north increases y');
equal(unplaced.advance(), false, 'north edge blocks');
equal(unplaced.snapshot()!.y, 1, 'blocked north does not move');
equal(unplaced.turnRight(), true, 'turn right succeeds');
equal(unplaced.snapshot()!.heading, Heading.East, 'right rotates clockwise');
equal(unplaced.advance(), true, 'east advance');
equal(unplaced.snapshot()!.x, 2, 'east increases x');
equal(unplaced.advance(), false, 'east edge blocks');
equal(unplaced.snapshot()!.x, 2, 'blocked east does not move');

equal(unplaced.turnLeft(), true, 'turn left succeeds');
equal(unplaced.snapshot()!.heading, Heading.North, 'left rotates counterclockwise');
assert(unplaced.place(1, 1, Heading.South), 'replace placement');
equal(unplaced.advance(), true, 'south advance');
equal(unplaced.snapshot()!.y, 0, 'south decreases y');
equal(unplaced.advance(), false, 'south edge blocks');
assert(unplaced.place(1, 0, Heading.West), 'west placement');
equal(unplaced.advance(), true, 'west advance');
equal(unplaced.snapshot()!.x, 0, 'west decreases x');
equal(unplaced.advance(), false, 'west edge blocks');

const cycle = new Navigator(1, 1);
cycle.place(0, 0, Heading.North);
cycle.turnLeft();
equal(cycle.snapshot()!.heading, Heading.West, 'left wraps north to west');
cycle.turnRight();
equal(cycle.snapshot()!.heading, Heading.North, 'right wraps west to north');

